// Parse metadata filter search
// Supports filtering by:
// - department: QHSE, Engineering, Operations
// - document_type_category: process, form, template, policy
// - document_type: pdf, docx, xlsx
// - is_process, is_form, is_template: boolean
// - fleet_type, train_id, network_component: railway-specific
// - standard_compliance: ISO standards
// - processing_profile: railway, technical, general

const query = $json.query || $json.body?.query || '';
const filters = $json.filters || $json.body?.filters || {};
const limit = $json.limit || $json.body?.limit || 20;

// Build Qdrant filter structure
const qdrantFilters = {
  must: []
};

// Department filter
if (filters.department) {
  qdrantFilters.must.push({
    key: 'department',
    match: { value: filters.department }
  });
}

// Document type category
if (filters.document_type_category) {
  qdrantFilters.must.push({
    key: 'document_type_category',
    match: { value: filters.document_type_category }
  });
}

// Boolean flags
if (filters.is_process !== undefined) {
  qdrantFilters.must.push({
    key: 'is_process',
    match: { value: filters.is_process }
  });
}

if (filters.is_form !== undefined) {
  qdrantFilters.must.push({
    key: 'is_form',
    match: { value: filters.is_form }
  });
}

if (filters.is_template !== undefined) {
  qdrantFilters.must.push({
    key: 'is_template',
    match: { value: filters.is_template }
  });
}

// Railway-specific filters
if (filters.fleet_type) {
  qdrantFilters.must.push({
    key: 'fleet_type',
    match: { value: filters.fleet_type }
  });
}

if (filters.train_id) {
  qdrantFilters.must.push({
    key: 'train_id',
    match: { value: filters.train_id }
  });
}

if (filters.network_component) {
  qdrantFilters.must.push({
    key: 'network_component',
    match: { value: filters.network_component }
  });
}

return {
  json: {
    query,
    limit,
    filters: qdrantFilters.must.length > 0 ? qdrantFilters : {},
    min_score: filters.min_score || 0.6
  }
};

// Format filtered results
const response = $json;

if (response.status === 'error') {
  return {
    json: {
      success: false,
      error: response.message,
      results: []
    }
  };
}

const results = (response.results || []).map(result => ({
  document_id: result.document_id,
  document_name: result.metadata?.document_name,
  department: result.metadata?.department,
  document_type_category: result.metadata?.document_type_category,
  content_preview: (result.text || '').substring(0, 200),
  relevance_score: result.score,
  is_process: result.metadata?.is_process,
  is_form: result.metadata?.is_form,
  is_template: result.metadata?.is_template,
  fleet_type: result.metadata?.fleet_type,
  train_id: result.metadata?.train_id,
  standard_compliance: result.metadata?.standard_compliance,
  document_url: result.metadata?.document_url
}));

return {
  json: {
    success: true,
    results,
    filters_applied: $('Build Metadata Filters').item.json.filters,
    total_results: results.length
  }
};
